UPDATE navigate_units SET title='At the café · Words & forms',edition='ORBIT Original Practice · 2026',status='published',steps='[{"mediaUrl":"","type":"vocabulary","skill":"vocabulary","title":"Vocabulary","instructions":"Изучи слова: послушай произношение, проверь перевод, затем выполни проверку.","words":[{"word":"bread","meaning":"хлеб"},{"word":"rice","meaning":"рис"},{"word":"water","meaning":"вода"},{"word":"milk","meaning":"молоко"},{"word":"coffee","meaning":"кофе"},{"word":"tea","meaning":"чай"},{"word":"juice","meaning":"сок"},{"word":"cheese","meaning":"сыр"}],"questions":[{"type":"choice","prompt":"Выбери перевод: bread","options":["торт","хлеб","банан"],"answer":1,"explanation":"Выбери перевод: bread — хлеб","word":"bread"},{"type":"choice","prompt":"Выбери перевод: rice","options":["рис","апельсин","меню"],"answer":0,"explanation":"Выбери перевод: rice — рис","word":"rice"},{"type":"choice","prompt":"Выбери перевод: water","options":["яйцо","счёт в кафе","вода"],"answer":2,"explanation":"Выбери перевод: water — вода","word":"water"},{"type":"choice","prompt":"Выбери перевод: milk","options":["голодный","молоко","курица"],"answer":1,"explanation":"Выбери перевод: milk — молоко","word":"milk"},{"type":"choice","prompt":"Выбери перевод: coffee","options":["кофе","рыба","испытывающий жажду"],"answer":0,"explanation":"Выбери перевод: coffee — кофе","word":"coffee"},{"type":"choice","prompt":"Выбери перевод: tea","options":["салат","сладкий","чай"],"answer":2,"explanation":"Выбери перевод: tea — чай","word":"tea"},{"type":"choice","prompt":"Выбери перевод: juice","options":["очень вкусный","сок","суп"],"answer":1,"explanation":"Выбери перевод: juice — сок","word":"juice"},{"type":"choice","prompt":"Выбери перевод: cheese","options":["сыр","сэндвич","хлеб"],"answer":0,"explanation":"Выбери перевод: cheese — сыр","word":"cheese"}]},{"mediaUrl":"/orbit-lessons/A1-5-1-f524077a49fa.mp4","type":"video","skill":"grammar","title":"some / any","instructions":"At the