UPDATE navigate_units SET title='Better choices · Skills & review',edition='ORBIT Original Practice · 2026',status='published',steps='[{"mediaUrl":"","type":"vocabulary","skill":"vocabulary","title":"Vocabulary","instructions":"Изучи слова: послушай произношение, проверь перевод, затем выполни проверку.","words":[{"word":"discount","meaning":"скидка"},{"word":"receipt","meaning":"чек"},{"word":"refund","meaning":"возврат денег"},{"word":"exchange","meaning":"обменивать"},{"word":"online","meaning":"в интернете"},{"word":"in stock","meaning":"в наличии"},{"word":"out of stock","meaning":"нет в наличии"},{"word":"recommend","meaning":"рекомендовать"}],"questions":[{"type":"choice","prompt":"Выбери перевод: discount","options":["скидка","ценность","простой"],"answer":0,"explanation":"Выбери перевод: discount — скидка","word":"discount"},{"type":"choice","prompt":"Выбери перевод: receipt","options":["выбор","тяжёлый","чек"],"answer":2,"explanation":"Выбери перевод: receipt — чек","word":"receipt"},{"type":"choice","prompt":"Выбери перевод: refund","options":["лёгкий по весу","возврат денег","сравнивать"],"answer":1,"explanation":"Выбери перевод: refund — возврат денег","word":"refund"},{"type":"choice","prompt":"Выбери перевод: exchange","options":["обменивать","покупатель","переполненный"],"answer":0,"explanation":"Выбери перевод: exchange — обменивать","word":"exchange"},{"type":"choice","prompt":"Выбери перевод: online","options":["отзыв","спокойный","в интернете"],"answer":2,"explanation":"Выбери перевод: online — в интернете","word":"online"},{"type":"choice","prompt":"Выбери перевод: in stock","options":["удобный по условиям","в наличии","надёжный"],"answer":1,"explanation":"Выбери перевод: in stock — в наличии","word":"in stock"},{"type":"choice","prompt":"Выбери перевод: out of stock","options":["нет в наличии","современный","доступный по цене"],"answer":0,"explanation":"Выбери перевод: out of stock — нет в наличии","word":"out of stock"},{"type":"choice","promp