UPDATE navigate_units SET title='Making your point · Skills & review',edition='ORBIT Original Practice · 2026',status='published',steps='[{"mediaUrl":"","type":"vocabulary","skill":"vocabulary","title":"Vocabulary","instructions":"Изучи слова: послушай произношение, проверь перевод, затем выполни проверку.","words":[{"word":"claim","meaning":"утверждение"},{"word":"counterargument","meaning":"контраргумент"},{"word":"balanced","meaning":"взвешенный"},{"word":"convincing","meaning":"убедительный"},{"word":"relevant","meaning":"относящийся к делу"},{"word":"specific","meaning":"конкретный"},{"word":"support a claim","meaning":"подкрепить утверждение"},{"word":"draw a conclusion","meaning":"сделать вывод"}],"questions":[{"type":"choice","prompt":"Выбери перевод: claim","options":["в результате","утверждение","однако"],"answer":1,"explanation":"Выбери перевод: claim — утверждение","word":"claim"},{"type":"choice","prompt":"Выбери перевод: counterargument","options":["контраргумент","поэтому","для того чтобы"],"answer":0,"explanation":"Выбери перевод: counterargument — контраргумент","word":"counterargument"},{"type":"choice","prompt":"Выбери перевод: balanced","options":["тем не менее","чтобы","взвешенный"],"answer":2,"explanation":"Выбери перевод: balanced — взвешенный","word":"balanced"},{"type":"choice","prompt":"Выбери перевод: convincing","options":["преимущество","убедительный","несмотря на"],"answer":1,"explanation":"Выбери перевод: convincing — убедительный","word":"convincing"},{"type":"choice","prompt":"Выбери перевод: relevant","options":["относящийся к делу","кроме того","недостаток"],"answer":0,"explanation":"Выбери перевод: relevant — относящийся к делу","word":"relevant"},{"type":"choice","prompt":"Выбери перевод: specific","options":["с другой стороны","доказательство","конкретный"],"answer":2,"explanation":"Выбери перевод: specific — конкретный","word":"specific"},{"type":"choice","prompt":"Выбери перевод: support a claim","options":["рассуждение","подк